/bin/bash -lc "python - <<'PY'
import pathlib,re
for f in sorted(pathlib.Path('/docs').glob('*.txt')):
 s=f.read_text(); pages=re.split(r'--- page (\\d+) ---',s)
 print('\\nFILE',f.name[:-4])
 for i in range(1,len(pages),2):
  p,t=pages[i:i+2]; lines=t.splitlines(); hits=[n for n,l in enumerate(lines) if re.search(r'audit|inspect|examin|books|records|verif',l,re.I)]
  for n in hits:
   print('PAGE',p,':',' '.join(lines[max(0,n-2):min(len(lines),n+4)]))
PY"

